INSERT INTO treatments (title, slug, description, content, pdf_url, icon) VALUES
('Epidural Steroid Injection', 'epidural-steroid-injection', 'A minimally invasive procedure to relieve pain caused by inflamed spinal nerves.', 'Epidural steroid injections deliver anti-inflammatory medication directly into the epidural space around the spinal cord and nerve roots. This treatment is effective for reducing inflammation and pain caused by herniated discs, spinal stenosis, or sciatica. The procedure typically takes 15-30 minutes and can provide relief lasting from weeks to months.', '/documents/epidural-information.pdf', 'Syringe'),
('Facet Joint Injection - Lower Back', 'facet-joint-pain', 'Targeted injections to reduce pain and inflammation in the facet joints of the lower spine.', 'Facet joint injections are used to diagnose and treat pain originating from the facet joints in the lumbar spine. These small joints between vertebrae can become painful due to arthritis, injury, or degeneration. The injection contains both an anesthetic for immediate pain relief and a steroid to reduce long-term inflammation.', '/documents/facet-joint-pain-information.pdf', 'Target'),
('Facet Joint Injection - Neck', 'facet-neck-pain', 'Relief for cervical facet joint pain through precise medication delivery.', 'Cervical facet joint injections target the small joints in the neck that can cause pain, stiffness, and headaches. This procedure helps diagnose the source of neck pain and provides therapeutic relief through a combination of local anesthetic and anti-inflammatory medication. Many patients experience significant improvement in mobility and pain reduction.', '/documents/facet-neck-pain-information.pdf', 'Target'),
('Ketamine Infusion Therapy', 'ketamine-infusion', 'Advanced treatment for chronic pain conditions and complex regional pain syndrome.', 'Ketamine infusion therapy is an innovative treatment for chronic pain that has not responded to conventional therapies. Low-dose ketamine works by blocking NMDA receptors, which can help reset pain pathways in the nervous system. This treatment is particularly effective for conditions like CRPS, neuropathic pain, and fibromyalgia.', '/documents/ketamine-infusion-information.pdf', 'Droplet'),
('Lidocaine Infusion Therapy', 'lidocaine-infusion', 'Intravenous lidocaine treatment for neuropathic and chronic pain conditions.', 'Lidocaine infusion therapy involves administering lidocaine intravenously to treat various chronic pain conditions, particularly neuropathic pain. This treatment can help reduce pain signals and provide longer-lasting relief than typical pain medications. It is often used for conditions like diabetic neuropathy, post-herpetic neuralgia, and other nerve pain syndromes.', '/documents/lidocaine-infusion-information.pdf', 'Droplet'),
('Nerve Block Injections', 'nerve-pain', 'Targeted injections to block pain signals from specific nerves.', 'Nerve block injections deliver medication directly to or around specific nerves to interrupt pain signals traveling to the brain. This treatment can be both diagnostic (to identify the source of pain) and therapeutic (to provide pain relief). Various types of nerve blocks can address different pain conditions affecting the spine, joints, and peripheral nerves.', '/documents/nerve-pain-information.pdf', 'Zap'),
('Radiofrequency Ablation (RFA)', 'radiofrequency-ablation', 'Long-lasting pain relief through controlled nerve lesioning using heat.', 'Radiofrequency ablation uses heat generated by radio waves to create a lesion on specific nerves, disrupting their ability to transmit pain signals. This minimally invasive procedure can provide significant pain relief lasting from 6 months to over a year. RFA is commonly used for facet joint pain, sacroiliac joint pain, and other chronic pain conditions.', '/documents/rfa-information.pdf', 'Zap'),
('Sacroiliac Joint Injection', 'sacroiliac-joint', 'Treatment for lower back and leg pain originating from the SI joint.', 'Sacroiliac joint injections target the SI joint, which connects the spine to the pelvis. Dysfunction or inflammation of this joint can cause lower back, buttock, and leg pain. The injection combines a local anesthetic for immediate relief and a corticosteroid for longer-term anti-inflammatory effects, helping diagnose and treat SI joint pain.', '/documents/sij-information.pdf', 'Target'),
('Spinal Cord Stimulation', 'spinal-cord-stimulation', 'Advanced implantable device therapy for chronic pain management.', 'Spinal cord stimulation involves implanting a small device that sends electrical impulses to the spinal cord, masking pain signals before they reach the brain. This treatment is considered for patients with chronic pain who have not found relief with other treatments. The system is programmable and can be adjusted to provide optimal pain relief for various conditions including failed back surgery syndrome and CRPS.', '/documents/spinal-cord-stimulation-information.pdf', 'Cpu');
